-- 0003_tokens.sql — issued-token store (audit item R1: token lifecycle).
--
-- The service can mint durable API tokens through
-- POST /v1/orgs/{org}/tokens: org-bound, optional expiry, optional scope.
-- Credential plaintexts are shown once at creation and NEVER stored — the
-- `token_hash` column holds `<salt-hex>$<sha256-hex>` where the salt is a
-- per-record random value generated by the service (salt stored alongside
-- the digest, as password hashes are; the salt is not secret material).
--
-- Conventions follow 0001/0002:
-- - `bridge_` table prefix so the service can share a database;
-- - timestamps are ISO-8601 UTC text (as generated by the service), so
--   lexicographic comparison is chronologically correct — expiry and
--   revocation checks compare strings/parse them, no column types needed;
-- - `id` is the credential id (a service-generated UUID, also embedded in
--   the token plaintext for direct indexed lookup).

CREATE TABLE IF NOT EXISTS bridge_tokens (
    id         text    PRIMARY KEY,
    org_id     text    NOT NULL,
    name       text,
    token_hash text    NOT NULL,
    scope      text    NOT NULL,
    created_at text    NOT NULL,
    expires_at text,
    revoked_at text,
    created_by text    NOT NULL
);

-- List endpoint: per-org, newest first.
CREATE INDEX IF NOT EXISTS bridge_tokens_org_idx
    ON bridge_tokens (org_id, created_at DESC);
